273	// ForEachAgent runs fn as a parallel subtest for every registered agent.
274	// It handles repo setup, concurrency gating, context timeout, and cleanup.
275	// The timeout is scaled by each agent's TimeoutMultiplier.
276	//
277	// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
278	// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
279	// panic and restarts the entire scenario with a fresh repository, up to
280	// maxScenarioRestarts times. This avoids stale CLI session state from the
281	// failed attempt poisoning the retry.
282	func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
283		t.Helper()
284		t.Parallel()
285		all := agents.All()
286		if len(all) == 0 {
287			t.Skip("no agents registered (check E2E_AGENT filter)")
288		}
289		for _, agent := range all {
290			t.Run(agent.Name(), func(t *testing.T) {
291				// Use the global test deadline for slot wait so we don't
292				// skip prematurely — only bail if the whole binary is dying.
293				slotCtx := context.Background()
294				if deadline, ok := t.Deadline(); ok {
295					var cancel context.CancelFunc
296					slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
297					defer cancel()
298				}
299				if err := agents.AcquireSlot(slotCtx, agent); err != nil {
300					t.Fatalf("timed out waiting for agent slot: %v", err)
301				}
302				defer agents.ReleaseSlot(agent)
303	
304				// Per-test timeout starts after slot is acquired, scaled
305				// by the agent's multiplier (e.g. 2.5× for gemini).
306				scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
307	
308				var prevState *RepoState
309				for attempt := range maxScenarioRestarts + 1 {
310					s := SetupRepo(t, agent)
311					ctx, cancel := context.WithTimeout(context.Background(), scaled)
312	
313					// On restart, suppress artifact capture from the previous
314					// failed attempt so it doesn't overwrite the final one.
315					if prevState != nil {
316						prevState.skipArtifacts = true
317					}
318	
319					restarted := runScenario(t, s, ctx, fn)
320					cancel()
321	
322					if !restarted {
323						return
324					}
325					prevState = s
326					if attempt >= maxScenarioRestarts {
327						t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
328					}
329					t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
330				}
331			})
332		}
333	}
334	
335	// runScenario runs the test function and recovers from errScenarioRestart
336	// panics triggered by transient API errors in RunPrompt. Returns true if
337	// the scenario should be restarted with a fresh repository.
338	func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
339		t.Helper()
340		defer func() {
341			if r := recover(); r != nil {
342				if _, ok := r.(errScenarioRestart); ok {
343					restarted = true
344					return
345				}
346				panic(r) // re-panic for unexpected panics
347			}
348		}()
349		fn(t, s, ctx)
350		return false
351	}
352	
353	const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
354	
355	// errScenarioRestart is panicked by RunPrompt when a transient API error is
356	// detected. ForEachAgent recovers from this panic and restarts the test
357	// scenario with a fresh repository, avoiding stale CLI state from the failed
358	// attempt.
359	type errScenarioRestart struct {
360		msg string
361	}
362	
363	// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
364	// and returns the result. If the agent reports a transient API error, it
365	// panics with errScenarioRestart to trigger a full scenario restart in
366	// ForEachAgent (see runScenario).
367	func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
368		t.Helper()
369		out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
370		s.logPromptResult(out)
371	
372		if err != nil && s.Agent.IsTransientError(out, err) {
373			errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
374			t.Logf("%s — restarting scenario", errMsg)
375			fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
376			panic(errScenarioRestart{msg: errMsg})
377		}
378	
379		return out, err
380	}
381	
382	func (s *RepoState) logPromptResult(out agents.Output) {
383		s.ConsoleLog.WriteString("> " + out.Command + "\n")
384		s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
385		s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
386	}
