388	// Git runs a git command in the repo and logs it to ConsoleLog.
389	func (s *RepoState) Git(t *testing.T, args ...string) {
390		t.Helper()
391		s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
392		Git(t, s.Dir, args...)
393	}
