395	// StartSession starts an interactive session and registers it for pane
396	// capture in artifacts. Returns nil if the agent does not support interactive
397	// mode. The session is closed automatically during test cleanup.
398	func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
399		t.Helper()
400		session, err := s.Agent.StartSession(ctx, s.Dir)
401		if err != nil {
402			t.Fatalf("start session: %v", err)
403		}
404		if session == nil {
405			return nil
406		}
407		s.session = session
408		return session
409	}
