411	// WaitFor waits for a pattern in the interactive session's pane and logs the
412	// pane content to ConsoleLog after the wait completes (success or failure).
413	func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
414		t.Helper()
415		content, err := session.WaitFor(pattern, timeout)
416		fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
417		if err != nil {
418			t.Fatalf("WaitFor(%q): %v", pattern, err)
419		}
420	}
