439	// PatchSettings merges extra keys into .entire/settings.json.
440	func PatchSettings(t *testing.T, dir string, extra map[string]any) {
441		t.Helper()
442		path := filepath.Join(dir, ".entire", "settings.json")
443		data, err := os.ReadFile(path)
444		if err != nil {
445			t.Fatalf("read settings: %v", err)
446		}
447		var settings map[string]any
448		if err := json.Unmarshal(data, &settings); err != nil {
449			t.Fatalf("parse settings: %v", err)
450		}
451		for k, v := range extra {
452			settings[k] = v
453		}
454		out, err := json.MarshalIndent(settings, "", "  ")
455		if err != nil {
456			t.Fatalf("marshal settings: %v", err)
457		}
458		if err := os.WriteFile(path, out, 0o644); err != nil {
459			t.Fatalf("write settings: %v", err)
460		}
461	}
