463	// EmptyDir returns the path to an empty temporary directory, cleaned up when
464	// the test finishes. Useful as a cross-platform replacement for /dev/null in
465	// git config paths like core.hooksPath (git on Windows cannot open NUL).
466	func EmptyDir(t *testing.T) string {
467		t.Helper()
468		return t.TempDir()
