471	// Git runs a git command in the given directory and fails the test if it
472	// returns a non-zero exit code.
473	func Git(t *testing.T, dir string, args ...string) {
474		t.Helper()
475	
476		cmd := exec.Command("git", args...)
477		if dir != "" {
478			cmd.Dir = dir
479		}
480		cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
481	
482		out, err := cmd.CombinedOutput()
483		if err != nil {
484			t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
485		}
486	}
