488	// GitOutput runs a git command in the given directory, returns its trimmed
489	// stdout, and fails the test on error.
490	func GitOutput(t *testing.T, dir string, args ...string) string {
491		t.Helper()
492	
493		cmd := exec.Command("git", args...)
494		if dir != "" {
495			cmd.Dir = dir
496		}
497	
498		out, err := cmd.Output()
499		if err != nil {
500			var stderr string
501			ee := &exec.ExitError{}
502			if errors.As(err, &ee) {
503				stderr = string(ee.Stderr)
504			}
505			t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
506		}
507	
508		return strings.TrimSpace(string(out))
509	}
