511	// NewCheckpointCommits returns the SHAs of commits added to the
512	// entire/checkpoints/v1 branch since the test was set up, oldest first.
513	func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
514		t.Helper()
515	
516		log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
517		if log == "" {
518			return nil
519		}
520		return strings.Split(log, "\n")
521	}
