548	// ReadCheckpointMetadata reads the checkpoint-level metadata.json from the
549	// tip of the checkpoint branch for the given checkpoint ID.
550	func ReadCheckpointMetadata(t *testing.T, dir string, checkpointID string) CheckpointMetadata {
551		t.Helper()
552	
553		path := CheckpointPath(checkpointID) + "/metadata.json"
554		blob := "entire/checkpoints/v1:" + path
555	
556		raw := GitOutput(t, dir, "show", blob)
557	
558		var meta CheckpointMetadata
559		if err := json.Unmarshal([]byte(raw), &meta); err != nil {
560			t.Fatalf("unmarshal checkpoint metadata from %s: %v", blob, err)
561		}
562	
563		return meta
564	}
