566	// ReadSessionMetadata reads a session's metadata.json from the tip of the
567	// checkpoint branch for the given checkpoint ID and session index.
568	func ReadSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int) SessionMetadata {
569		t.Helper()
570	
571		path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
572		blob := "entire/checkpoints/v1:" + path
573	
574		raw := GitOutput(t, dir, "show", blob)
575	
576		var meta SessionMetadata
577		if err := json.Unmarshal([]byte(raw), &meta); err != nil {
578			t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
579		}
580	
581		return meta
582	}
