584	// WaitForSessionMetadata polls until session metadata exists on the checkpoint
585	// branch for the given checkpoint ID and session index, then returns it.
586	// This handles the race where the checkpoint branch advances before session
587	// metadata is fully committed.
588	func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
589		t.Helper()
590	
591		path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
592		blob := "entire/checkpoints/v1:" + path
593	
594		deadline := time.Now().Add(timeout)
595		for time.Now().Before(deadline) {
596			raw := gitOutputSafe(dir, "show", blob)
597			if raw != "" {
598				var meta SessionMetadata
599				if err := json.Unmarshal([]byte(raw), &meta); err != nil {
600					t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
601				}
602				return meta
603			}
604			time.Sleep(500 * time.Millisecond)
605		}
606		t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
607		return SessionMetadata{}
608	}
609	
610	// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
611	// the initial commit. Returns the bare repo path.
612	func SetupBareRemote(t *testing.T, s *RepoState) string {
613		t.Helper()
614	
615		var bareDir string
616		if os.Getenv("E2E_KEEP_REPOS") != "" {
617			var err error
618			bareDir, err = os.MkdirTemp("", "e2e-bare-*")
619			if err != nil {
620				t.Fatalf("create bare remote dir: %v", err)
621			}
622			t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
623		} else {
624			bareDir = t.TempDir()
625		}
626	
627		Git(t, bareDir, "init", "--bare")
628		Git(t, s.Dir, "remote", "add", "origin", bareDir)
629		Git(t, s.Dir, "push", "-u", "origin", "HEAD")
630		return bareDir
631	}
632	
633	// GitOutputErr runs a git command and returns (output, error) without
634	// failing the test. For commands expected to fail.
635	func GitOutputErr(dir string, args ...string) (string, error) {
636		cmd := exec.Command("git", args...)
637		if dir != "" {
638			cmd.Dir = dir
639		}
640		out, err := cmd.CombinedOutput()
641		return strings.TrimSpace(string(out)), err
642	}
643	
644	// GetCheckpointTrailer extracts the Entire-Checkpoint trailer value from a
645	// code commit. Returns the trimmed trailer value, or an empty string if the
646	// trailer is not present.
647	func GetCheckpointTrailer(t *testing.T, dir string, ref string) string {
648		t.Helper()
649	
650		return GitOutput(t, dir, "log", "-1", "--format=%(trailers:key=Entire-Checkpoint,valueonly)", ref)
651	}
