25	var (
26		// ErrEmptyCommit occurs when a commit is attempted using a clean
27		// working tree, with no changes to be committed.
28		ErrEmptyCommit = errors.New("cannot create empty commit: clean working tree")
29		// ErrCannotCherryPickWithoutCommitOptions happens when no commitOptions is not provided for cherry-picking commit
30		ErrCannotCherryPickWithoutCommitOptions = errors.New("cannot cherry-pick without commit options")
31	
32		// characters to be removed from user name and/or email before using them to build a commit object
33		// See https://git-scm.com/docs/git-commit#_commit_information
34		invalidCharactersRe = regexp.MustCompile(`[<>\n]`)
35	)
36	
37	// Commit stores the current contents of the index in a new commit along with
38	// a log message from the user describing the changes.
39	func (w *Worktree) Commit(msg string, opts *CommitOptions) (plumbing.Hash, error) {
40		if trace.Performance.Enabled() {
41			start := time.Now()
42			defer func() {
43				trace.Performance.Printf("performance: %.9f s: git command: git commit", time.Since(start).Seconds())
44			}()
45		}
46	
47		if err := opts.Validate(w.r); err != nil {
48			return plumbing.ZeroHash, err
49		}
50	
51		if opts.All {
52			if err := w.autoAddModifiedAndDeleted(); err != nil {
53				return plumbing.ZeroHash, err
54			}
55		}
56	
57		if opts.Amend {
58			head, err := w.r.Head()
59			if err != nil {
60				return plumbing.ZeroHash, err
61			}
62			headCommit, err := w.r.CommitObject(head.Hash())
63			if err != nil {
64				return plumbing.ZeroHash, err
65			}
66	
67			opts.Parents = headCommit.ParentHashes
68		}
69	
70		idx, err := w.r.Storer.Index()
71		if err != nil {
72			return plumbing.ZeroHash, err
73		}
74	
75		// First handle the case of the first commit in the repository being empty.
76		if len(opts.Parents) == 0 && len(idx.Entries) == 0 && !opts.AllowEmptyCommits {
77			return plumbing.ZeroHash, ErrEmptyCommit
78		}
79	
80		h := &buildTreeHelper{
81			fs: w.Filesystem,
82			s:  w.r.Storer,
83		}
84	
85		treeHash, err := h.BuildTree(idx, opts)
86		if err != nil {
87			return plumbing.ZeroHash, err
88		}
89	
90		previousTree := plumbing.ZeroHash
91		if len(opts.Parents) > 0 {
92			parentCommit, err := w.r.CommitObject(opts.Parents[0])
93			if err != nil {
94				return plumbing.ZeroHash, err
95			}
96			previousTree = parentCommit.TreeHash
97		}
98	
99		if treeHash == previousTree && !opts.AllowEmptyCommits {
100			return plumbing.ZeroHash, ErrEmptyCommit
101		}
102	
103		commit, err := w.buildCommitObject(msg, opts, treeHash)
104		if err != nil {
105			return plumbing.ZeroHash, err
106		}
107	
108		return commit, w.updateHEAD(commit)
109	}
110	
111	// CherryPick cherry picks commits and merge them into the worktree based on the selected
112	// merge strategy. Each commit sits on the top of worktree's current head.
113	// It resembles `git cherry-pick <commit-hash-1> <commit-hash-2> ... --strategy-option [theirs,ours]`
114	func (w *Worktree) CherryPick(commitOpts *CommitOptions, ortStrategyOption OrtMergeStrategyOption, commits ...*object.Commit) error {
115		if commitOpts == nil {
116			return ErrCannotCherryPickWithoutCommitOptions
117		}
118	
119		for _, commit := range commits {
120			var changes object.Changes
121			headRef, err := w.r.Head()
122			if err != nil {
123				return err
124			}
125			headCommit, err := w.r.CommitObject(headRef.Hash())
126			if err != nil {
127				return err
128			}
129			currentTree, err := headCommit.Tree()
130			if err != nil {
131				return err
132			}
133	
134			commitTree, err := commit.Tree()
135			if err != nil {
136				return err
137			}
138	
139			switch ortStrategyOption {
140			case TheirsMergeStrategy:
141				changes, err = currentTree.Diff(commitTree)
142			case OursMergeStrategy:
143				changes, err = commitTree.Diff(currentTree)
144			}
145	
146			if err != nil {
147				return err
148			}
149			for _, change := range changes {
150				action, err := change.Action()
151				if err != nil {
152					return err
153				}
154	
155				switch action {
156				case merkletrie.Delete:
157					if _, err := w.Remove(change.From.Name); err != nil {
158						return err
159					}
160				case merkletrie.Insert, merkletrie.Modify:
161					_, to, err := change.Files()
162					if err != nil {
163						return err
164					}
165					content, err := to.Contents()
166					if err != nil {
167						return err
168					}
169					dstFile, err := w.Filesystem.Create(to.Name)
170					if err != nil {
171						return err
172					}
173					_, err = dstFile.Write([]byte(content))
174					if err != nil {
175						return err
176					}
177					if _, err := w.Add(to.Name); err != nil {
178						return err
179					}
180				}
181			}
182			_, err = w.Commit(commit.Message, &CommitOptions{
183				Author:            &commit.Author,
184				Committer:         commitOpts.Committer,
185				Signer:            commitOpts.Signer,
186				AllowEmptyCommits: commitOpts.AllowEmptyCommits,
187			})
188			if err != nil {
189				return err
190			}
191		}
192		return nil
193	}
