195	func (w *Worktree) autoAddModifiedAndDeleted() error {
196		s, err := w.Status()
197		if err != nil {
198			return err
199		}
200	
201		idx, err := w.r.Storer.Index()
202		if err != nil {
203			return err
204		}
205	
206		for path, fs := range s {
207			if fs.Worktree != Modified && fs.Worktree != Deleted {
208				continue
209			}
210	
211			if _, _, err := w.doAddFile(idx, s, path, nil); err != nil {
212				return err
213			}
214		}
215	
216		return w.r.Storer.SetIndex(idx)
217	}
