219	func (w *Worktree) updateHEAD(commit plumbing.Hash) error {
220		head, err := w.r.Storer.Reference(plumbing.HEAD)
221		if err != nil {
222			return err
223		}
224	
225		name := plumbing.HEAD
226		if head.Type() != plumbing.HashReference {
227			name = head.Target()
228		}
229	
230		ref := plumbing.NewHashReference(name, commit)
231		return w.r.Storer.SetReference(ref)
232	}
