234	func (w *Worktree) buildCommitObject(msg string, opts *CommitOptions, tree plumbing.Hash) (plumbing.Hash, error) {
235		commit := &object.Commit{
236			Author:       w.sanitize(*opts.Author),
237			Committer:    w.sanitize(*opts.Committer),
238			Message:      msg,
239			TreeHash:     tree,
240			ParentHashes: opts.Parents,
241		}
242	
243		signer := opts.Signer
244		if signer == nil {
245			cfg, err := w.r.ConfigScoped(config.SystemScope)
246			if err == nil && cfg != nil && cfg.Commit.GpgSign.IsTrue() {
247				// Use Has before Get so the key is not frozen when no plugin is
248				// registered, allowing callers to register one later.
249				if !plugin.Has(plugin.ObjectSigner()) {
250					return plumbing.ZeroHash, fmt.Errorf("cannot auto-sign commit: disable commit.gpgSign or register an ObjectSigner plugin")
251				}
252	
253				signer, err = plugin.Get(plugin.ObjectSigner())
254				if err != nil {
255					return plumbing.ZeroHash, fmt.Errorf("get object signer: %w", err)
256				}
257			}
258		}
259	
260		if signer != nil {
261			sig, err := signObject(signer, commit)
262			if err != nil {
263				return plumbing.ZeroHash, err
264			}
265			commit.Signature = string(sig)
266		}
267	
268		obj := w.r.Storer.NewEncodedObject()
269		if err := commit.Encode(obj); err != nil {
270			return plumbing.ZeroHash, err
271		}
272		return w.r.Storer.SetEncodedObject(obj)
273	}
