275	func (w *Worktree) sanitize(signature object.Signature) object.Signature {
276		return object.Signature{
277			Name:  invalidCharactersRe.ReplaceAllString(signature.Name, ""),
278			Email: invalidCharactersRe.ReplaceAllString(signature.Email, ""),
279			When:  signature.When,
280		}
281	}
