283	// buildTreeHelper converts a given index.Index file into multiple git objects
284	// reading the blobs from the given filesystem and creating the trees from the
285	// index structure. The created objects are pushed to a given Storer.
286	type buildTreeHelper struct {
287		fs billy.Filesystem
288		s  storage.Storer
289	
290		trees   map[string]*object.Tree
291		entries map[string]*object.TreeEntry
292	}
293	
294	// BuildTree builds the tree objects and push its to the storer, the hash
295	// of the root tree is returned.
296	func (h *buildTreeHelper) BuildTree(idx *index.Index, _ *CommitOptions) (plumbing.Hash, error) {
297		const rootNode = ""
298		h.trees = map[string]*object.Tree{rootNode: {}}
299		h.entries = map[string]*object.TreeEntry{}
300	
301		for _, e := range idx.Entries {
302			if err := h.commitIndexEntry(e); err != nil {
303				return plumbing.ZeroHash, err
304			}
305		}
306	
307		return h.copyTreeToStorageRecursive(rootNode, h.trees[rootNode])
308	}
